> +	/* Return an error so the benchmark can run repeatedly without rmmod. */
> +	pr_info("Region allocation benchmark complete\n");
> +	ret = -EAGAIN;
> +out:
> +	kvfree(reg_idx);
> +	kvfree(reg_sz);
> +	kvfree(bitmap);
